use vstd::prelude::*;
use vstd::string::string_view::StringView;

verus! {
    // Specification: ASCII alphabetic test
    spec fn is_ascii_letter(c: char) -> bool {
        ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
    }

    // Specification: does the sequence s satisfy the conditions?
    spec fn spec_check(s: Seq<char>) -> bool {
        s.len() > 0
        && is_ascii_letter(s.index(s.len() - 1))
        && (if s.len() == 1 {
                true
           } else {
                s.index(s.len() - 2) == ' '
           })
    }

    // Implementation over &str, using StringView to get a Seq<char>
    fn check_if_last_char_is_a_letter(txt: &str) -> bool
        ensures
            // Relate the return value to our spec over the sequence of chars
            let sv = StringView::from_str(txt).chars;
            result == spec_check(sv)
    {
        let view = StringView::from_str(txt);
        let chars: Seq<char> = view.chars;
        let len: nat = chars.len();

        // If empty, can't satisfy non-empty requirement
        if len == 0 {
            return false;
        }

        // Initialize prev and last to the first character
        let mut prev: char = chars.index(0);
        let mut last: char = chars.index(0);
        let mut i: nat = 1;

        // Walk through chars to end, keeping track of the last two
        while i < len
            invariant 1 <= i && i <= len,
            invariant last == chars.index(i - 1),
            invariant (i >= 2 ==> prev == chars.index(i - 2)),
            decreases len - i
        {
            prev = last;
            last = chars.index(i);
            i = i + 1;
        }

        // Now `last` is the final character, `prev` is the one before if len>=2
        if !is_ascii_letter(last) {
            return false;
        }
        if len == 1 {
            return true;
        }
        prev == ' '
    }
}

